import argparse
import json
import os

import pandas as pd

REPO_ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


def create_failure_atlas(input_json_path: str, output_json_path: str):
    """
    Parses instance-level RAVEL evaluation results to create a "Failure Atlas".

    The atlas is built based on a strict criterion: it only includes instances
    from (target_attribute, corrupted_attribute) pairs where *every single*
    instance resulted in an isolation failure.

    Args:
        input_json_path (str): Path to the JSON file from the evaluation script.
        output_json_path (str): Path to save the resulting Failure Atlas JSON file.
    """
    print(f"Loading instance-level results from: {input_json_path}")

    try:
        with open(input_json_path) as f:
            data = json.load(f)
        # The actual results are nested under the 'instance_results' key
        instance_results = data.get("instance_results")
        if not instance_results:
            print("Error: 'instance_results' key not found in the JSON file.")
            return
    except (json.JSONDecodeError, FileNotFoundError) as e:
        print(f"Error loading or parsing JSON file: {e}")
        return

    # Convert the list of dictionaries to a pandas DataFrame for efficient processing
    df = pd.DataFrame(instance_results)

    print(f"Loaded {len(df)} total instances for analysis.")

    # --- Step 1: Identify attribute pairs with 100% isolation failure ---

    # Group all instances by the combination of their target and corrupted attributes
    grouped = df.groupby(["target_attribute", "corrupted_attribute"])

    systematic_failure_pairs = []
    for name, group in grouped:
        # The strict condition: check if the isolation_metric is 0.0 for ALL instances in the group.
        # We also ensure the cause_metric was 1.0 for all, as it's only an isolation failure if the edit worked.
        is_systematic_failure = (group["isolation_metric"] == 0.0).all() and (
            group["cause_metric"] == 1.0
        ).all()

        if is_systematic_failure:
            systematic_failure_pairs.append(name)
            print(f"  -> Found systematic failure pair: {name}")

    if not systematic_failure_pairs:
        print(
            "\nNo attribute pairs with 100% isolation failure were found. The Failure Atlas will be empty."
        )
        failure_atlas = []
    else:
        print(
            f"\nIdentified {len(systematic_failure_pairs)} pairs with consistent failures. Building atlas..."
        )
        # --- Step 2: Build the Failure Atlas from these pairs ---

        # Filter the original DataFrame to keep only the instances belonging to the identified failure pairs
        failure_df = df[
            df.set_index(["target_attribute", "corrupted_attribute"]).index.isin(
                systematic_failure_pairs
            )
        ]

        # Convert the filtered DataFrame back to a list of dictionaries
        failure_atlas = failure_df.to_dict(orient="records")

    # --- Step 3: Save the Failure Atlas ---
    print(
        f"Saving Failure Atlas with {len(failure_atlas)} instances to: {output_json_path}"
    )

    # Create the directory if it doesn't exist
    os.makedirs(os.path.dirname(output_json_path), exist_ok=True)

    with open(output_json_path, "w") as f:
        json.dump(failure_atlas, f, indent=4)

    print("Failure Atlas creation complete.")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(
        description="Create a RAVEL Failure Atlas from instance-level evaluation results."
    )
    parser.add_argument(
        "input_json",
        type=str,
        help="Path to the input JSON file generated by the instance-level evaluation script.",
    )
    parser.add_argument(
        "--output_json",
        type=str,
        default=os.path.join(
            REPO_ROOT,
            "data/artifacts/ravel/failure_atlas/ravel_failure_atlas.json",
        ),
        help="Path to save the output Failure Atlas JSON file.",
    )
    args = parser.parse_args()

    create_failure_atlas(args.input_json, args.output_json)
